function downloadJson(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function currentMetadata(){return {support_type:currentSupportType,version:'V1.4-ZPM',components:definition().components.map(c=>({id:c.id,status:c.status})),steel_arch:componentIsActive('steel_arch')?steelParameters():undefined,advance_support:AdvanceSupportRegistry.has(currentSupportType)?{parameters:advanceSupportParametersFor(),validation:lastAdvanceValidation}:undefined,lattice_arch:LatticeArchRegistry.has(currentSupportType)?{parameters:latticeArchParametersFor(),validation:lastLatticeValidation,representation:'THREE_LEG_LATTICE_TRUE_REBAR_GEOMETRY'}:undefined,zpm_lining:isZpmSupport()?{parameters:zpmParametersFor(),validation:lastZpmValidation,rebar_applicability_status:ZpmLiningRegistry.get(currentSupportType).rebar_applicability_status}:undefined,primary_concrete:supportsProfileParametric()?{parameters:primaryConcreteParameters(),validation:lastPrimaryValidation}:undefined,secondary_lining:supportsProfileParametric()?{parameters:secondaryLiningParameters(),validation:lastSecondaryValidation}:undefined,primary_secondary_spatial_relation:lastSpatialValidation,component_dependency_validation:supportsProfileParametric()?(lastDependencyValidation||updateDependencyValidation()):null,variant_id:variant.variant_id,user_overrides:variant.user_overrides,export_coordinate_state:'FORMAL_NON_EXPLODED'}}
async function applyPresentationQuery(){const q=new URLSearchParams(location.search),requestedSupport=q.get('support_type')||q.get('support');if(requestedSupport)await switchSupportType(requestedSupport);if(q.get('variant')){const shared=variantsForSupport(currentSupportType).find(item=>item.variant_id===q.get('variant'));if(shared){const candidate=hydrateSharedVariant(shared,basePayload),check=validateVariantGeometry(candidate);variant=candidate;lastSpatialValidation=check.relation;lastDependencyValidation=check.dependency;lastZpmValidation=check.zpm;lastInvalidFeedback=null;variantsBySupport.set(currentSupportType,variant);updateComponents(Object.keys(ComponentDependencyMap));renderParameterFeedback();$('variantName').value=variant.variant_name||'方案A';$('variantStatus').textContent='已载入共享方案：'+variant.variant_name}}if(q.get('component'))selectComponent(q.get('component'));if(q.has('beta')&&selectedComponent==='steel_arch'){applyParameter('beta_deg',+q.get('beta'));buildParameterEditor()}if(q.get('helpers')==='1'){$('helperMaster').checked=true;const details=$('helperMaster').closest('details');if(details)details.open=true;buildHelpers()}if(q.get('panel')){document.querySelectorAll('details').forEach(d=>{if(d.querySelector('summary')?.textContent===q.get('panel')){d.open=true;d.scrollIntoView({block:'start'})}})}if(q.get('view'))setView(q.get('view'))}
async function init(){[state,lockData,payloads,profileDatabase,baseProfileParameters]=await Promise.all([fetch('../outputs/master_demo/ZZ-Va_support_master_state.json').then(r=>r.json()),fetch('../outputs/lock_foot_anchor/ZZ-Va_lock_foot_anchor_geometry.json').then(r=>r.json()),fetch('../outputs/master_demo/support_payloads_v1_2.json').then(r=>r.json()),fetch('../database/steel_profiles.json').then(r=>r.json()),fetch('../outputs/base_profile/ZZ-Va_base_profile_parameters.json').then(r=>r.json())]);buildSupportSelect();await switchSupportType('ZZ-Va');await applyPresentationQuery()}

$('supportSelect').onchange=e=>switchSupportType(e.target.value).catch(err=>$('updateStatus').textContent=err.message);
$('recognizeDrawing').onclick=async()=>{const file=$('drawingFile').files[0];if(!file)return $('drawingProgress').textContent='请先选择图纸';try{const fd=new FormData();fd.append('file',file);const response=await fetch('/api/master/drawing',{method:'POST',body:fd}),data=await response.json();if(!response.ok)throw new Error(data.message);applyDrawingResult(data)}catch(e){$('drawingProgress').innerHTML=`<b class="pending">FAILED</b>：${e.message}`}};
$('demoCache').onclick=async()=>{try{const response=await fetch('/api/master/demo-cache'),data=await response.json();if(data.status!=='ok')throw new Error(data.message);applyDrawingResult(data)}catch(e){$('drawingProgress').textContent='未找到可用OCR缓存，可上传图纸重新识别。'}};
$('restoreRecognized').onclick=()=>{if(!selectedComponent)return;const affected=activeDependencies(selectedComponent);restoreComponent(variant,selectedComponent);updateComponents(affected);lastDependencyValidation=updateDependencyValidation();lastAdjustment={component:selectedComponent,affected,checked:['steel_arch','secondary_lining'].filter(id=>componentIsActive(id)&&!affected.includes(id))};lastInvalidFeedback=null;buildParameterEditor();buildHelpers();renderParameterFeedback();$('updateStatus').textContent='已恢复识别值'};$('restoreReference').onclick=$('restoreRecognized').onclick;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('resetCamera').onclick=()=>{setExploded(false);resetCamera()};$('explodeDistance').oninput=()=>{$('explodeValue').textContent=(+$('explodeDistance').value).toFixed(1)+'m';if(exploded)setExploded(true)};['helperMaster','helperLabels','helperCenters','helperRadii','helperAngles','helperDistances','helperAxes'].forEach(id=>$(id).onchange=buildHelpers);
$('saveVariant').onclick=()=>{try{const check=validateVariantGeometry(variant);lastSpatialValidation=check.relation;lastDependencyValidation=check.dependency;lastZpmValidation=check.zpm;lastInvalidFeedback=null;renderParameterFeedback();variant.variant_name=$('variantName').value||'方案A';variant.support_type=currentSupportType;variant.base_support_type=currentSupportType;variant.created_time=variant.created_time||new Date().toISOString();const record=sharedVariantRecord(variant,schemaFor);record.geometry_check={status:$('feedbackStatus').textContent,dependency:lastDependencyValidation,zpm:lastZpmValidation,checked_time:new Date().toISOString()};saveVariantToLibrary(record);downloadJson(`SupportVariant_${currentSupportType}_${variant.variant_name}.json`,record);$('variantStatus').textContent=`方案已保存到共享库：${variant.variant_name} · 几何检查 ${record.geometry_check.status}`}catch(error){lastInvalidFeedback=error.message;renderParameterFeedback({invalid:lastInvalidFeedback});$('variantStatus').textContent='方案未保存：'+error.message}};
$('loadVariant').onchange=async e=>{try{const record=JSON.parse(await e.target.files[0].text());if(record.support_type!==currentSupportType)throw new Error('VARIANT_SUPPORT_TYPE_MISMATCH');const candidate=hydrateSharedVariant(record,basePayload),check=validateVariantGeometry(candidate);variant=candidate;lastSpatialValidation=check.relation;lastDependencyValidation=check.dependency;lastZpmValidation=check.zpm;lastInvalidFeedback=null;variantsBySupport.set(currentSupportType,variant);updateComponents(Object.keys(ComponentDependencyMap));saveVariantToLibrary(sharedVariantRecord(variant,schemaFor));buildParameterEditor();buildHelpers();renderParameterFeedback();$('variantStatus').textContent='方案已加载并加入共享库：'+variant.variant_name}catch(err){lastInvalidFeedback=err.message;renderParameterFeedback({invalid:lastInvalidFeedback});$('variantStatus').textContent='加载失败：'+err.message}};
$('exportGlb').onclick=()=>{setExploded(false);clearHighlight();const exportType=currentSupportType;new GLTFExporter().parse(model,b=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([b],{type:'model/gltf-binary'}));a.href=url;a.download=`${exportType}_support_current.glb`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);highlightSelected()},e=>alert('导出失败：'+e.message),{binary:true,onlyVisible:true})};
$('exportMetadata').onclick=()=>downloadJson(`${currentSupportType}_support_current_metadata.json`,currentMetadata());
canvas.addEventListener('dblclick',()=>{const g=groupByName(component(selectedComponent||'steel_arch')?.group);if(!g)return;const box=new THREE.Box3().setFromObject(g),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length();controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(size*.8,size*.35,size));controls.update()});addEventListener('resize',render);init().catch(e=>$('drawingProgress').textContent='初始化失败：'+e.message);

window.masterDemoV12={switchSupportType,getCurrentSupportType:()=>currentSupportType,getSteelParameters:steelParameters,getVariant:()=>publicVariant(variant),getDefinition:()=>definition(),exportMetadata:currentMetadata,setSteelParameter:(key,value)=>{selectedComponent='steel_arch';applyParameter(key,value)}};

